sed -i 's/val taskOrchestrator/val _isFlashTaskMode = kotlinx.coroutines.flow.MutableStateFlow(io.agents.pokeclaw.utils.KVUtils.isFlashTaskMode())\n    val isFlashTaskMode: kotlinx.coroutines.flow.StateFlow<Boolean> = _isFlashTaskMode.asStateFlow()\n\n    fun toggleFlashTaskMode() {\n        val current = _isFlashTaskMode.value\n        _isFlashTaskMode.value = !current\n        io.agents.pokeclaw.utils.KVUtils.setFlashTaskMode(!current)\n    }\n\n    val taskOrchestrator/g' app/src/main/java/io/agents/pokeclaw/AppViewModel.kt
sed -i 's/maxIterations = 1000/maxIterations = if (isFlashTaskMode.value) 10 else 1000,\n            keepRecentRounds = if (isFlashTaskMode.value) 1 else 3/g' app/src/main/java/io/agents/pokeclaw/AppViewModel.kt
